//! PCM → DSD: interpolation up to the bit rate (`interp`), then a one-bit
//! modulator of order 5, 7 or 9 (`modulator`). The coefficient tables are
//! generated by `tools/dsd/design_sdm.py`.

mod interp;
mod lookahead;
#[cfg(test)]
pub(crate) mod measure;
pub(crate) mod modulator;
pub(crate) mod tables;
#[cfg(test)]
mod tests;

use super::{encoder_ratio, DsdEncoder, DsdError, DsdRate, ModulatorKind, PCM_FULL_SCALE_MODULATION};
use interp::Interpolator;
use modulator::Sdm;
use tables::{SdmCoefs, SDM5, SDM5_WIDE, SDM7, SDM7_WIDE, SDM9};

pub fn new_encoder(
    kind: ModulatorKind,
    input_rate: u32,
    rate: DsdRate,
) -> Result<Box<dyn DsdEncoder>, DsdError> {
    let unsupported = DsdError::UnsupportedModulator { kind, multiple: rate.multiple };
    if !kind.supports(rate) {
        return Err(unsupported);
    }
    Ok(match kind {
        ModulatorKind::Sdm5 => Box::new(SdmEncoder::<5>::new(&SDM5, input_rate, rate)?),
        ModulatorKind::Sdm5Wide => Box::new(SdmEncoder::<5>::new(&SDM5_WIDE, input_rate, rate)?),
        ModulatorKind::Sdm7 => Box::new(SdmEncoder::<7>::new(&SDM7, input_rate, rate)?),
        ModulatorKind::Sdm7Wide => Box::new(SdmEncoder::<7>::new(&SDM7_WIDE, input_rate, rate)?),
        ModulatorKind::Sdm9 => Box::new(SdmEncoder::<9>::new(&SDM9, input_rate, rate)?),
        k if k.info().search != super::Search::None => return lookahead::new_encoder(k, input_rate, rate),
        // Not built yet (stage 4: docs/18 §4).
        _ => return Err(unsupported),
    })
}

/// The kind that `kind` is at `multiple` under another name: a plainer
/// (lower in rank) kind whose search there is the very same, as SDM7 LA+ at
/// DSD256 is SDM7 LA (`lookahead::setup_for`). None when it is its own.
pub fn same_as(kind: ModulatorKind, multiple: u32) -> Option<ModulatorKind> {
    let own = lookahead::setup_for(kind, multiple)?;
    super::CATALOG
        .iter()
        .filter(|i| i.rank > kind.info().rank && lookahead::setup_for(i.kind, multiple) == Some(own))
        .min_by_key(|i| i.rank)
        .map(|i| i.kind)
}

/// The plain (no search) table of a kind, for the measurements.
#[cfg(test)]
pub(crate) fn plain_table(kind: ModulatorKind) -> Option<&'static [SdmCoefs]> {
    match kind {
        ModulatorKind::Sdm5 => Some(&SDM5),
        ModulatorKind::Sdm5Wide => Some(&SDM5_WIDE),
        ModulatorKind::Sdm7 => Some(&SDM7),
        ModulatorKind::Sdm7Wide => Some(&SDM7_WIDE),
        ModulatorKind::Sdm9 => Some(&SDM9),
        _ => None,
    }
}

/// The coefficient set for a rate multiple. The 48 kHz family uses the same
/// sets: its band edges sit 8.8 % higher.
pub(crate) fn coefs_for(table: &'static [SdmCoefs], rate: DsdRate) -> Option<&'static SdmCoefs> {
    table.iter().find(|k| k.multiple == rate.multiple)
}

/// Interpolation and a plain modulator of order N.
pub(crate) struct SdmEncoder<const N: usize> {
    ratio: usize,
    interp: Interpolator,
    pub(crate) sdm: Sdm<N>,
}

#[cfg(test)]
pub(crate) type Sdm5Encoder = SdmEncoder<5>;

impl<const N: usize> SdmEncoder<N> {
    /// `table` must hold a set for `rate` (the catalog's rates).
    pub(crate) fn new(table: &'static [SdmCoefs], input_rate: u32, rate: DsdRate) -> Result<Self, DsdError> {
        let ratio = encoder_ratio(input_rate, rate)?;
        let coefs = coefs_for(table, rate).expect("a coefficient set for every catalog rate");
        Ok(SdmEncoder {
            ratio,
            interp: Interpolator::new(ratio, input_rate as f64 / rate.base as f64),
            sdm: Sdm::new(coefs),
        })
    }
}

impl<const N: usize> DsdEncoder for SdmEncoder<N> {
    fn ratio(&self) -> usize {
        self.ratio
    }

    fn process(&mut self, pcm: &[f64], out: &mut [u8]) {
        assert_eq!(out.len(), pcm.len() * self.ratio / 8);
        let block = self.interp.block_inputs();
        for (part, bytes) in pcm.chunks(block).zip(out.chunks_mut(block * self.ratio / 8)) {
            // Garbage (NaN, ±inf) must not reach the filters' history.
            let up = self.interp.process(part, |s| {
                if s.is_nan() { 0.0 } else { s.clamp(-4.0, 4.0) * PCM_FULL_SCALE_MODULATION }
            });
            self.sdm.run(up, bytes);
        }
    }

    fn reset(&mut self) {
        self.interp.reset();
        self.sdm.reset();
    }

    fn overloads(&self) -> u64 {
        self.sdm.overloads()
    }
}
